#include "EngineGenerator.hpp"
#include "../Utils/FileWriter.hpp"
#include "../XIR/XirNode.hpp"
#include "../XIR/XirGraph.hpp"
#include "../XIR/XirValidator.hpp"
#include "../XIR/XirOptimizer.hpp"
#include <filesystem>
namespace exotic { void EngineGenerator::Generate(const std::string& name){ XirGraph graph; XirNode node; node.id=name+"Engine"; node.name=name+"Engine"; node.type="Engine"; node.purpose="Core Exotic engine generated through XIR."; node.capabilities={"Initialize","Observe","Update","Shutdown"}; node.states={"Created","Active","Paused","Error","Destroyed"}; node.events={name+"Started",name+"Observed",name+"Updated",name+"Shutdown"}; graph.AddNode(node); if(!XirValidator::Validate(graph)) return; XirOptimizer::Optimize(graph); std::string root="Engines/"+name+"Engine"; std::filesystem::create_directories(root); FileWriter::Write(root+"/"+name+"Engine.hpp","#pragma once\n\n////////////////////////////////////////////////////////////\n/// EXOTIC XIR ENGINE\n/// Engine: "+name+"Engine\n/// Source: XIR Node\n////////////////////////////////////////////////////////////\n\n#include ^<string^>\n#include ^<vector^>\n\nnamespace exotic\n{\n\nclass "+name+"Engine\n{\npublic:\n    "+name+"Engine();\n    void Initialize();\n    void Observe(const std::string^& input);\n    void Update();\n    void Shutdown();\n\nprivate:\n    bool initialized = false;\n    std::vector^<std::string^> observations;\n};\n\n}\n"); FileWriter::Write(root+"/"+name+"Engine.cpp","#include \""+name+"Engine.hpp\"\n#include ^<iostream^>\n\nnamespace exotic\n{\n\n"+name+"Engine::"+name+"Engine() {}\n\nvoid "+name+"Engine::Initialize()\n{\n    initialized = true;\n    std::cout ^<^< \""+name+"Engine initialized from XIR.\" ^<^< std::endl;\n}\n\nvoid "+name+"Engine::Observe(const std::string^& input)\n{\n    observations.push_back(input);\n}\n\nvoid "+name+"Engine::Update()\n{\n    if (!initialized) return;\n}\n\nvoid "+name+"Engine::Shutdown()\n{\n    initialized = false;\n}\n\n}\n"); FileWriter::Write(root+"/"+name+"Engine.xir.md","# XIR NODE: "+name+"Engine\n\nType: Engine\n\nPurpose: Core Exotic engine generated through XIR.\n\n## Capabilities\n\n- Initialize\n- Observe\n- Update\n- Shutdown\n\n## States\n\n- Created\n- Active\n- Paused\n- Error\n- Destroyed\n\n## Events\n\n- "+name+"Started\n- "+name+"Observed\n- "+name+"Updated\n- "+name+"Shutdown\n"); } }
